///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92018.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function () {
};

/**
 * @method
 * @name init
 * @description 화면 초기화
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    $c.win.setEnterKeyEvent(grp_search, scwin.btn_search_onclick);
    scwin.getParam = $c.data.getParameter();
    await scwin.listSync();
};

