/**
 * @method
 * @name img_Close_onclick
 * @description img_Close 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function () {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92018.img_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 조회 버튼
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_search_onclick = async function (e) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92018.btn_search_onclick" });
    }
};

/**
 * @method
 * @name grd_oncelldblclick
 * @description 목록 더블클릭
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        const callbackParam = {
            empNo: dlt_selectListRes.getCellData(rowIndex, "empNo"),
            empNm: dlt_selectListRes.getCellData(rowIndex, "empNm"),
            depCd: dlt_selectListRes.getCellData(rowIndex, "depCd"),
            depNm: dlt_selectListRes.getCellData(rowIndex, "depNm")
        }
        $c.win.closePopup(callbackParam);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92018.grd_oncelldblclick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 닫기 버튼
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92018.btn_close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function () {
    let strDepCd = "";
    if (scwin.getParam !== undefined) {
        // strDepCd = (arrPar.length >= 1 ? arrPar[0] : "");
        // scwin.strCdSch = (arrPar.length >= 2 ? arrPar[1] : ""); // 조회 후 위치할 사원번호
        strDepCd = scwin.getParam.depCd;
    }

    dma_selectListReq.set("depCd", strDepCd);
    dma_selectListReq.set("empNm", ibx_search.getValue());
    const sbmOptions = {
        id: "sbm_selectList",
        action: "/api/listing/common/pop/etc/select-list-examiner",
        method: "get",
        ref: "dma_selectListReq",
        target: "dlt_selectListRes=body",
        isProcessMsg: false
    };
    await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name sbm_selectList_submitdone
 * @description 목록 조회 콜백
 * @returns {void}
 * @hidden N
 */
scwin.sbm_selectList_submitdone = function () {
    tbx_totCnt.setValue(dlt_selectListRes.getRowCount());
};
